import { sql } from "drizzle-orm";
import {
  check,
  foreignKey,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  unique,
  uniqueIndex,
  type AnyPgColumn,
} from "drizzle-orm/pg-core";

import { organization, project } from "./tenancy.ts";
import { user } from "./identity.ts";
import { createdAt, idText, moment, prefixCheck, updatedAt } from "./columns.ts";
import { newRevision } from "../revisions.ts";

/**
 * A persona is the person an agent gets tested against: synthetic, and
 * reusable across any number of tests. These tables hold who they are —
 * nothing about what they want on a given occasion (the test's business) and
 * nothing about how the agent under test is reached.
 *
 * Two tables so that two different things can be pointed at. A test names the
 * identity row — this persona, however they currently behave. A run
 * pins a version row — this persona, frozen exactly as they were when
 * the simulation happened, so editing today never rewrites what an old result
 * meant. Renames touch the identity row only; behavior lives in the version.
 *
 * **A Custom persona is archived, never deleted.** Archive takes it out
 * of the lists somebody authors from and leaves every historical row exactly
 * where it was. Egma-provided personas have null tenancy, stay active and
 * read-only, and can be forked into a Custom persona for customization.
 * Permanent removal is a compliance workflow and is not this table's business.
 */

export const persona = pgTable(
  "persona",
  {
    id: idText("id").primaryKey(),
    /** Null together with projectId when this is an Egma-provided persona. */
    organizationId: idText("organization_id").references(
      () => organization.id,
      { onDelete: "cascade" },
    ),
    /** Null together with organizationId for an Egma-provided persona. */
    projectId: idText("project_id"),
    name: text("name").notNull(),
    description: text("description"),
    /**
     * Circular with the version table on purpose; the constraint is deferred
     * so create can insert both rows in one transaction.
     */
    currentVersionId: idText("current_version_id")
      .notNull()
      .references((): AnyPgColumn => personaVersion.id),
    /**
     * The opaque token an edit, an Archive or a Restore has to name to be
     * allowed to land — see `revisions.ts`. Defaulted here rather than at each
     * call site so that catalog seeding and the Custom factory cannot
     * come to disagree about filling it.
     */
    revision: text("revision").notNull().$defaultFn(newRevision),
    archivedAt: moment("archived_at"),
    createdBy: idText("created_by").references(() => user.id, {
      onDelete: "set null",
    }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    prefixCheck("persona_id_prefix", table.id, "prs"),
    check(
      "persona_tenancy_is_whole_or_egmas",
      sql`(${table.organizationId} is null) = (${table.projectId} is null)`,
    ),
    check(
      "persona_egma_provided_is_active",
      sql`${table.organizationId} is not null or ${table.archivedAt} is null`,
    ),
    // The pairing, not each column on its own: a persona cannot name
    // one organization and another organization's project.
    foreignKey({
      name: "persona_project_organization_fk",
      columns: [table.projectId, table.organizationId],
      foreignColumns: [project.id, project.organizationId],
    }).onDelete("cascade"),
    // An Egma-provided name resolves to one catalog identity. Custom names
    // may still repeat because callers can select them by stable id.
    uniqueIndex("persona_egma_provided_name_unique")
      .on(table.name)
      .where(sql`${table.organizationId} is null`),
    index("persona_organization_id_project_id_idx")
      .on(table.organizationId, table.projectId)
      .where(sql`${table.archivedAt} is null`),
  ],
);

export const personaVersion = pgTable(
  "persona_version",
  {
    id: idText("id").primaryKey(),
    personaId: idText("persona_id")
      .notNull()
      .references(() => persona.id, { onDelete: "cascade" }),
    version: integer("version").notNull(),
    /** Human behavior only. Technical execution choices live in `models`. */
    traits: jsonb("traits").notNull(),
    /**
     * The complete LLM, STT and TTS selection pinned by this version.
     *
     * Required with no default: a version that cannot say how it executes is
     * corrupt data. Credentials are resolved for each claimed work item and
     * never belong in this immutable authored value.
     */
    models: jsonb("models").notNull(),
    createdBy: idText("created_by").references(() => user.id, {
      onDelete: "set null",
    }),
    createdAt: createdAt(),
  },
  (table) => [
    prefixCheck("persona_version_id_prefix", table.id, "prsv"),
    // A version is a complete executable value at the database boundary, not
    // only after the TypeScript reader has interpreted its jsonb. Exact keys
    // keep technical voice out of traits and prevent a stale writer from
    // putting a second model owner back beside `models`.
    check(
      "persona_version_traits_valid",
      sql`
        jsonb_typeof(${table.traits}) is not distinct from 'object'
        and (${table.traits} - array[
          'personality', 'language', 'manner', 'patience', 'accent',
          'backgroundNoise', 'underFriction'
        ]::text[]) is not distinct from '{}'::jsonb
        and jsonb_typeof(${table.traits}->'personality') is not distinct from 'string'
        and nullif(btrim(${table.traits}->>'personality'), '') is not null
        and jsonb_typeof(${table.traits}->'language') is not distinct from 'string'
        and nullif(btrim(${table.traits}->>'language'), '') is not null
        and (
          not (${table.traits} ? 'manner')
          or (
            jsonb_typeof(${table.traits}->'manner') is not distinct from 'string'
            and nullif(btrim(${table.traits}->>'manner'), '') is not null
          )
        )
        and (
          not (${table.traits} ? 'patience')
          or (
            jsonb_typeof(${table.traits}->'patience') is not distinct from 'string'
            and nullif(btrim(${table.traits}->>'patience'), '') is not null
          )
        )
        and (
          not (${table.traits} ? 'accent')
          or (
            jsonb_typeof(${table.traits}->'accent') is not distinct from 'string'
            and nullif(btrim(${table.traits}->>'accent'), '') is not null
          )
        )
        and (
          not (${table.traits} ? 'backgroundNoise')
          or (
            jsonb_typeof(${table.traits}->'backgroundNoise') is not distinct from 'string'
            and nullif(btrim(${table.traits}->>'backgroundNoise'), '') is not null
          )
        )
        and (
          not (${table.traits} ? 'underFriction')
          or (
            jsonb_typeof(${table.traits}->'underFriction') is not distinct from 'string'
            and nullif(btrim(${table.traits}->>'underFriction'), '') is not null
          )
        )
      `,
    ),
    check(
      "persona_version_models_valid",
      sql`
        jsonb_typeof(${table.models}) is not distinct from 'object'
        and (${table.models} - array['llm', 'stt', 'tts']::text[])
          is not distinct from '{}'::jsonb
        and (${table.models}->'llm') is not distinct from
          jsonb_build_object('provider', 'openai', 'model', 'gpt-4o-mini')
        and (
          (${table.models}->'stt') is not distinct from
            jsonb_build_object('provider', 'openai', 'model', 'gpt-live-transcribe')
          or (${table.models}->'stt') is not distinct from
            jsonb_build_object('provider', 'deepgram', 'model', 'nova-3-general')
        )
        and jsonb_typeof(${table.models}->'tts') is not distinct from 'object'
        and ((${table.models}->'tts') - array[
          'provider', 'model', 'voiceId', 'speed'
        ]::text[]) is not distinct from '{}'::jsonb
        and (
          (
            ${table.models}->'tts'->>'provider' is not distinct from 'cartesia'
            and ${table.models}->'tts'->>'model' is not distinct from 'sonic-3.5'
          )
          or (
            ${table.models}->'tts'->>'provider' is not distinct from 'openai'
            and ${table.models}->'tts'->>'model' is not distinct from 'gpt-4o-mini-tts'
          )
        )
        and jsonb_typeof(${table.models}->'tts'->'voiceId') is not distinct from 'string'
        and nullif(btrim(${table.models}->'tts'->>'voiceId'), '') is not null
        and jsonb_path_exists(
          ${table.models},
          '$.tts.speed ? (@.type() == "number" && @ >= 0.6 && @ <= 1.5)'::jsonpath
        )
      `,
    ),
    unique("persona_version_persona_id_version_unique").on(
      table.personaId,
      table.version,
    ),
    // The composite-foreign-key target that lets a simulation prove the
    // version it pins really is a version of the persona it names.
    unique("persona_version_id_persona_id_unique").on(
      table.id,
      table.personaId,
    ),
  ],
);
	'carrier_trunk_username', 'carrier_trunk_password'
));--> statement-breakpoint

-- The fixed catalog entry exists at the schema level, before any process
-- starts. Startup seeding therefore checks this row and becomes an idempotent
-- catalog reconciliation, not the operation that makes a project usable.
INSERT INTO "persona"
	("id", "organization_id", "project_id", "name", "description",
	 "current_version_id", "revision", "archived_at", "created_by",
	 "created_at", "updated_at")
VALUES
	('prs_01M0E4EVJ6ECGVJEA4NSBTC0CC', null, null, 'Default Persona',
	 'Regular conversationalist persona', 'prsv_01M0E4J0BBE1FVDVTZ1BSS5C97',
	 'rev_01M0E4EVJ6ECGVJEA4NSBTC0CD', null, null,
	 '2026-08-19T23:09:01.674Z'::timestamptz,
	 '2026-08-19T23:09:01.674Z'::timestamptz);--> statement-breakpoint
INSERT INTO "persona_version"
	("id", "persona_id", "version", "traits", "models", "created_by", "created_at")
VALUES
	('prsv_01M0E4J0BBE1FVDVTZ1BSS5C97',
	 'prs_01M0E4EVJ6ECGVJEA4NSBTC0CC',
	 1,
	 '{"personality":"Speaks clear, natural English. Starts patient and cooperative, answers one question at a time, and becomes firmer if the agent is confusing or repetitive without becoming rude.","language":"en-US","manner":"Clear, natural, and conversational.","patience":"Starts patient and gives the agent time to explain.","accent":"Neutral American English.","backgroundNoise":"None.","underFriction":"Becomes firmer if the agent is confusing or repetitive, without becoming rude."}'::jsonb,
	 '{"llm":{"provider":"openai","model":"gpt-4o-mini"},"stt":{"provider":"openai","model":"gpt-live-transcribe"},"tts":{"provider":"cartesia","model":"sonic-3.5","voiceId":"5ee9feff-1265-424a-9d7f-8e4d431a12c7","speed":1}}'::jsonb,
	 null,
	 '2026-08-19T23:09:01.674Z'::timestamptz);--> statement-breakpoint
-- Both halves of the circular identity/version insert now exist. Clear the
-- deferred pointer event before the project FK needs to lock persona again.
SET CONSTRAINTS "persona_current_version_id_persona_version_id_fk" IMMEDIATE;--> statement-breakpoint

-- A project always has one default. Existing custom choices stay untouched;
-- only rows that had no choice receive the fixed Egma-provided persona.
-- Drop the old nullable FK before the rewrite so the update does not queue a
-- trigger event that would block the NOT NULL schema change below.
ALTER TABLE "project" DROP CONSTRAINT "project_default_persona_id_persona_id_fk";--> statement-breakpoint
UPDATE "project"
SET "default_persona_id" = 'prs_01M0E4EVJ6ECGVJEA4NSBTC0CC'
WHERE "default_persona_id" IS NULL;--> statement-breakpoint
ALTER TABLE "project" ALTER COLUMN "default_persona_id" SET DEFAULT 'prs_01M0E4EVJ6ECGVJEA4NSBTC0CC';--> statement-breakpoint
ALTER TABLE "project" ALTER COLUMN "default_persona_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "project" ADD CONSTRAINT "project_default_persona_id_persona_id_fk"
FOREIGN KEY ("default_persona_id") REFERENCES "public"."persona"("id")
ON DELETE restrict ON UPDATE no action;--> statement-breakpoint

-- A normal foreign key cannot say "the persona is owned by this project OR by
-- Egma." Keep that rule in one database function and make every stored use of
-- a persona pass through it. Project ids are globally unique, so matching a
-- project-owned row also proves its organization.
import {
  RECOMMENDED_PERSONA_MODELS,
  type PersonaModels,
} from "../models/selections.ts";
import { EGMA_PROVIDED_PERSONAS } from "./ids.ts";

export { EGMA_PROVIDED_PERSONAS } from "./ids.ts";

/**
 * Human facts only. Provider, model, voice id and speed live in `models`.
 *
 * The optional facts are absent when nobody stated them. An empty string is
 * normalized to absence at the authoring boundary.
 */
export type PersonaTraits = {
  readonly personality: string;
  readonly language: string;
  /** How they come across: warm, brisk, formal, distracted. */
  readonly manner?: string | undefined;
  /** How long they will stay with something before they push. */
  readonly patience?: string | undefined;
  /** Where they sound like they are from. */
  readonly accent?: string | undefined;
  /** What is going on around them while they talk. */
  readonly backgroundNoise?: string | undefined;
  /** What they do when the agent gets it wrong, or will not budge. */
  readonly underFriction?: string | undefined;
};

export type EgmaProvidedPersonaVersion = {
  /** Fixed forever. A catalog edit adds a new id; it never changes this row. */
  readonly id: string;
  readonly version: number;
  readonly traits: PersonaTraits;
  readonly models: PersonaModels;
  readonly createdAt: Date;
};

export type EgmaProvidedPersona = {
  /** Fixed for the identity's whole life. */
  readonly id: string;
  readonly name: string;
  readonly description: string;
  readonly versions: readonly EgmaProvidedPersonaVersion[];
};

/**
 * Every persona Egma provides.
 *
 * Prior versions stay in this list. A change to behavior or execution adds a
 * new fixed version and makes it the last entry. This is what lets a fresh
 * installation understand a version that an older installation pinned.
 */
export const PERSONA_LIBRARY_CATALOG: readonly EgmaProvidedPersona[] = [
  {
    id: EGMA_PROVIDED_PERSONAS.defaultPersona,
    name: "Default Persona",
    description: "Regular conversationalist persona",
    versions: [
      {
        id: "prsv_01M0E4J0BBE1FVDVTZ1BSS5C97",
        version: 1,
        traits: {
          personality:
            "Speaks clear, natural English. Starts patient and cooperative, answers one question at a time, and becomes firmer if the agent is confusing or repetitive without becoming rude.",
          language: "en-US",
          manner: "Clear, natural, and conversational.",
          patience: "Starts patient and gives the agent time to explain.",
          accent: "Neutral American English.",
          backgroundNoise: "None.",
          underFriction:
            "Becomes firmer if the agent is confusing or repetitive, without becoming rude.",
        },
        models: RECOMMENDED_PERSONA_MODELS,
        createdAt: new Date("2026-08-19T23:09:01.674Z"),
      },
    ],
  },
];
/**
 * The model combinations this release can execute.
 *
 * A catalog entry is an adapter contract, not a suggestion. Provider and
 * model are kept together because an adapter supports the pair. Accepting the
 * two fields independently is what allowed a realtime OpenAI model to reach
 * the segmented transcription endpoint in production.
 */
export const MODEL_JOBS = ["llm", "stt", "tts"] as const;
export type ModelJob = (typeof MODEL_JOBS)[number];

export const MODEL_PROVIDERS = ["openai", "deepgram", "cartesia"] as const;
export type ModelProvider = (typeof MODEL_PROVIDERS)[number];

export type ProviderCatalogEntry = {
  readonly provider: ModelProvider;
  readonly job: ModelJob;
  readonly model: string;
  readonly label: string;
  readonly recommendedVoiceId?: string;
  readonly recommendedSpeed?: number;
};

export const PROVIDER_CATALOG = [
  {
    provider: "openai",
    job: "llm",
    model: "gpt-4o-mini",
    label: "OpenAI",
  },
  {
    // This is the realtime transcription adapter. It must never be sent to
    // OpenAI's segmented /v1/audio/transcriptions endpoint.
    provider: "openai",
    job: "stt",
    model: "gpt-live-transcribe",
    label: "OpenAI",
  },
  {
    provider: "deepgram",
    job: "stt",
    model: "nova-3-general",
    label: "Deepgram",
  },
  {
    provider: "cartesia",
    job: "tts",
    model: "sonic-3.5",
    label: "Cartesia",
    recommendedVoiceId: "5ee9feff-1265-424a-9d7f-8e4d431a12c7",
    recommendedSpeed: 1,
  },
  {
    provider: "openai",
    job: "tts",
    model: "gpt-4o-mini-tts",
    label: "OpenAI",
    recommendedVoiceId: "alloy",
    recommendedSpeed: 1,
  },
] as const satisfies readonly ProviderCatalogEntry[];

export const PROVIDERS_BY_JOB: {
  readonly [Job in ModelJob]: readonly ProviderCatalogEntry[];
} = {
  llm: PROVIDER_CATALOG.filter((entry) => entry.job === "llm"),
  stt: PROVIDER_CATALOG.filter((entry) => entry.job === "stt"),
  tts: PROVIDER_CATALOG.filter((entry) => entry.job === "tts"),
};

/** The first supported pair for each job is the release default. */
export const RECOMMENDED_ENTRY: {
  readonly [Job in ModelJob]: ProviderCatalogEntry;
} = {
  llm: firstEntryFor("llm"),
  stt: firstEntryFor("stt"),
  tts: firstEntryFor("tts"),
};

export function isModelProvider(provider: string): provider is ModelProvider {
  return MODEL_PROVIDERS.some((known) => known === provider);
}

export function catalogEntry(
  job: ModelJob,
  provider: string,
  model: string,
): ProviderCatalogEntry | undefined {
  return PROVIDERS_BY_JOB[job].find(
    (entry) => entry.provider === provider && entry.model === model,
  );
}

function firstEntryFor(job: ModelJob): ProviderCatalogEntry {
  const first = PROVIDERS_BY_JOB[job][0];
  if (first === undefined) {
    throw new Error(`the provider catalog ships no ${job} adapter`);
  }
  return first;
}

