        ) {
          throw new Error(
            `fixed Egma-provided persona version ${expected.id} already holds different content`,
          );
        }
      }

      if (identityChanges.length > 0 || versionInsertions.length > 0) {
        seeded.push({
          id: entry.id,
          name: entry.name,
          version: current.version,
          versionId: current.id,
        });
      }
    }
    return seeded;
  });
}

